#include "Logger.h"
#include <cstring>
void Logger::clear(){_head=0;_count=0;}void Logger::log(uint32_t timestamp,int angle,float distanceCm,bool alarm,const char* event,int16_t rssi){LogEntry& e=_entries[_head];e.timestamp=timestamp;e.angle=static_cast<int16_t>(constrain(angle,0,180));e.distanceCm=distanceCm<0?-1:static_cast<int16_t>(roundf(distanceCm));e.alarm=alarm;e.rssi=rssi;std::strncpy(e.event,event?event:"UNKNOWN",sizeof(e.event)-1);e.event[sizeof(e.event)-1]='\0';_head=(_head+1)%Config::MAX_LOG_ENTRIES;if(_count<Config::MAX_LOG_ENTRIES)++_count;}bool Logger::getEntry(size_t i,LogEntry& out)const{if(i>=_count)return false;const size_t first=(_head+Config::MAX_LOG_ENTRIES-_count)%Config::MAX_LOG_ENTRIES;out=_entries[(first+i)%Config::MAX_LOG_ENTRIES];return true;}String Logger::csvHeader()const{return "Timestamp,Angulo,Distancia_cm,Alarme,Evento,RSSI\n";}String Logger::csvLine(const LogEntry& e)const{String l;l.reserve(80);l+=String(e.timestamp);l+=',';l+=String(e.angle);l+=',';l+=String(e.distanceCm);l+=',';l+=e.alarm?"true":"false";l+=',';l+=e.event;l+=',';l+=String(e.rssi);l+='\n';return l;}
